from __future__ import annotations

import threading
from pathlib import Path
from typing import List, Optional

from k3dge.engine.contract import ContractExtractor, register_extractor

_IGNORED_DIRS = {".git", ".mypy_cache", ".next", ".pytest_cache", ".venv", "__pycache__", "build", "coverage", "dist", "node_modules", "out", "vendor", "venv"}
_GENERATED_MARKERS = (".generated.", ".min.")
_GENERATED_SUFFIXES = (".d.ts",)
_LANGUAGE = None
_LANGUAGE_LOCK = threading.Lock()


def _is_generated(path: Path) -> bool:
    name = path.name
    return any(m in name for m in _GENERATED_MARKERS) or name.endswith(_GENERATED_SUFFIXES)


# 未识别 node 类型的 **一次性** 告警（进程内每类一次）：把静默丢弃变成可观察降级
# （README L67「坏插件只 WARN、不红门禁」的口径：可见但不致命）。判读面据此知道契约可能残缺。
_UNRECOGNIZED: set = set()
_UNRECOGNIZED_LOCK = threading.Lock()


def _warn_unrecognized(kind: str, node_type: str) -> None:
    import sys
    with _UNRECOGNIZED_LOCK:
        key = (kind, node_type)
        if key in _UNRECOGNIZED:
            return
        _UNRECOGNIZED.add(key)
    print(f"[WARN][EXTRACTOR] typescript: unrecognized {kind} node type {node_type!r}",
          file=sys.stderr)


def _slice(source: bytes, node) -> str:
    text = source[node.start_byte : node.end_byte].decode("utf-8", "backslashreplace")
    return "".join(ch for ch in text if ch in "\n\t" or ch.isprintable()).strip()


def _strip_impl_body(text: str) -> str:
    """Drop the first `{ ... }` implementation body; keep signature / type members."""
    brace = text.find("{")
    if brace == -1:
        return text.rstrip()
    return text[:brace].rstrip()


def _body_node(node):
    """Grammar `body` field child (drilling through wrappers) — where the
    implementation starts. `None` for bodyless declarations."""
    b = node.child_by_field_name("body")
    if b is not None:
        return b
    for c in node.children:
        r = _body_node(c)
        if r is not None:
            return r
    return None


def _signature_text(source: bytes, node) -> str:
    """Declaration text **without** the body, sliced at the grammar `body` node.
    (Not `text.find("{")` — that truncates inline object return types, code-4.)"""
    b = _body_node(node)
    if b is None:
        return _slice(source, node)
    text = source[node.start_byte : b.start_byte].decode("utf-8", "backslashreplace")
    return "".join(ch for ch in text if ch in "\n\t" or ch.isprintable()).strip()


def _container_signature(source: bytes, node) -> str:
    header = _signature_text(source, node)
    methods: List[str] = []
    body = _body_node(node)
    for member in (body.children if body is not None else ()):
        if member.type in ("{", "}", ";"):
            continue
        if member.type in ("method_definition", "public_field_definition", "field_definition", "abstract_method_signature", "method_signature"):
            sig = _signature_text(source, member)
            if sig:
                methods.append("  " + sig)
        else:
            _warn_unrecognized("class member", member.type)
    if not methods:
        return header
    return header + "\n" + "\n".join(methods)


def _decl_signature(source: bytes, node, exported: bool = False, prefix: str = "") -> Optional[str]:
    if node.type in ("export_statement",):
        inner = None
        for child in node.children:
            if child.type in ("function_declaration", "method_definition") + ("class_declaration", "abstract_class_declaration") + ("interface_declaration", "type_alias_declaration", "enum_declaration") + ("lexical_declaration",):
                inner = child
                break
        if inner is None:
            _warn_unrecognized("top-level", next((c.type for c in node.named_children), node.type))
            return _slice(source, node)
        prefix = source[node.start_byte:inner.start_byte].decode("utf-8", "backslashreplace")
        prefix = "".join(ch for ch in prefix if ch in "\n\t" or ch.isprintable()).strip()
        return _decl_signature(source, inner, exported=True, prefix=prefix)
    elif node.type in ("class_declaration", "abstract_class_declaration"):
        text = _container_signature(source, node)
    elif node.type in ("function_declaration", "method_definition"):
        text = _signature_text(source, node)
    elif node.type in ("interface_declaration", "type_alias_declaration", "enum_declaration"):
        text = _slice(source, node)
    elif node.type in ("lexical_declaration",):
        if not exported:
            return None
        text = _signature_text(source, node)
    else:
        _warn_unrecognized("top-level", node.type)
        return None
    if prefix:
        return (prefix + " " + text).strip()
    return text


def _load_language():
    """Construct + cache the grammar Language (immutable ⇒ shareable across threads).
    A construction failure is re-raised as `ImportError` — `src/k3dge/engine/contract.py` treats that
    as a skip signal, so a broken grammar never reds the whole gate (never fatal)."""
    global _LANGUAGE
    if _LANGUAGE is not None:
        return _LANGUAGE
    import importlib
    try:
        from tree_sitter import Language
        _grammar = importlib.import_module("tree_sitter_typescript")
    except ImportError as exc:
        raise ImportError("tree-sitter-typescript not installed; pip install tree-sitter-typescript") from exc
    with _LANGUAGE_LOCK:
        if _LANGUAGE is None:
            try:
                lang = Language(_grammar.language_typescript())
            except AttributeError as exc:
                raise ImportError("tree-sitter-typescript grammar 缺 language_typescript: " + str(exc)) from exc
            except TypeError:
                try:
                    lang = Language(_grammar.language_typescript(), "typescript")  # type: ignore[call-arg]
                except (TypeError, AttributeError) as exc:
                    raise ImportError("tree-sitter-typescript grammar unusable: " + str(exc)) from exc
            except (ValueError, RuntimeError) as exc:
                raise ImportError("tree-sitter-typescript grammar unusable: " + str(exc)) from exc
            _LANGUAGE = lang
    return _LANGUAGE


def extract_typescript_interface(path: Path, include_doc: bool = False) -> str:
    from tree_sitter import Parser
    language = _load_language()
    try:
        parser = Parser(language)  # 0.21+（每次新建：Parser 非线程安全）
    except TypeError:
        parser = Parser()
        parser.language = language  # type: ignore[attr-defined]
    import os
    try:
        fd = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    except OSError as exc:
        raise ImportError("typescript: cannot open " + str(path) + " (" + str(exc) + ")") from exc
    try:
        chunks: List[bytes] = []
        while True:
            c = os.read(fd, 1 << 20)
            if not c:
                break
            chunks.append(c)
        source = b"".join(chunks)
    finally:
        os.close(fd)
    tree = parser.parse(source)
    if tree.root_node.has_error:
        _warn_unrecognized("parse-error", path.name)   # 残缺树：可见降级，不静默漏接口
    lines = []
    for node in tree.root_node.children:
        text = _decl_signature(source, node)
        if text:
            if include_doc:
                prev = node.prev_sibling
                if prev is not None and prev.type == "comment":
                    doc = _slice(source, prev).strip()
                    if doc:
                        text = doc + "\n" + text
            lines.append(text)
    return "\n".join(lines)


class TypescriptExtractor(ContractExtractor):
    def can_handle(self, path: Path) -> bool:
        # 绝对路径/`..` 未归一就比 `parts`：`src/link/x.ts`（link→node_modules）或
        # `a/../node_modules/x.ts` 都能绕过目录黑名单（判据落在未归一的形状上），故先归一再判（code-7）。
        import os

        if path.suffix not in (".ts", ".tsx", ".js"):
            return False
        parts = Path(os.path.normpath(str(path))).parts
        if ".." in parts or _IGNORED_DIRS.intersection(parts):
            return False
        if _is_generated(path):
            return False
        try:                              # 解析后仍不得越界（symlink 指向忽略目录 ⇒ 拒）
            resolved = Path(os.path.realpath(str(path)))
        except OSError:                   # pragma: no cover - 罕见 IO 故障
            return False
        if _IGNORED_DIRS.intersection(resolved.parts):
            return False
        # 黑名单不是包含性校验（code-6）：绝对路径必须落在仓根（cwd）内，否则可能是仓外符号链接靶。
        if path.is_absolute() and not resolved.is_relative_to(Path.cwd().resolve()):
            return False
        return True

    def extract(self, path: Path, include_doc: bool = False) -> str:
        return extract_typescript_interface(path, include_doc=include_doc)


register_extractor(TypescriptExtractor())
